import { ChangeDetectionStrategy, Component, input, output } from '@angular/core';
import { MatIconModule } from '@angular/material/icon';
export interface ScoreCard {
  id: string;
  label: string;
  value: string | number;
  hint: string;
  icon?: string;
  tone?: string;
  progress?: number;
}
@Component({
  selector: 'app-pattern-scorecards',
  imports: [MatIconModule],
  templateUrl: './scorecard-strip.component.html',
  styleUrl: './scorecard-strip.component.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ScorecardStripComponent {
  readonly cards = input.required<ScoreCard[]>();
  readonly selected = input('');
  readonly interactive = input(false);
  readonly iconLayout = input<'none' | 'inline' | 'tile'>('none');
  readonly compact = input(false);
  readonly selection = output<string>();
  choose(id: string): void {
    this.selection.emit(this.selected() === id ? '' : id);
  }
}

export type OrderStatus = 'pending' | 'active' | 'done';
export interface PatternOrder {
  id: number;
  code: string;
  name: string;
  region: string;
  status: OrderStatus;
  amount: number;
  owner: string;
}
export interface PatternQuery {
  search: string;
  status: string;
  region: string;
  sort: string;
}
export const EMPTY_QUERY: PatternQuery = { search: '', status: '', region: '', sort: 'code' };
export const STATUS_LABELS: Record<OrderStatus, string> = { pending: 'Chờ xử lý', active: 'Đang xử lý', done: 'Hoàn tất' };
export const REGIONS = ['Miền Bắc', 'Miền Trung', 'Miền Nam'];
export const normalizeSearch = (value: string) =>
  value
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[đĐ]/g, 'd')
    .toLowerCase()
    .trim();
export function queryOrders(records: readonly PatternOrder[], query: PatternQuery): PatternOrder[] {
  return records
    .filter(
      row =>
        (!query.status || row.status === query.status) &&
        (!query.region || row.region === query.region) &&
        normalizeSearch(row.code + ' ' + row.name).includes(normalizeSearch(query.search))
    )
    .sort(
      (a, b) => (query.sort === 'amount-desc' ? b.amount - a.amount : query.sort === 'amount-asc' ? a.amount - b.amount : 0) || a.id - b.id
    );
}
export function seedOrders(): PatternOrder[] {
  const names = ['An Phát', 'Minh Long', 'Bình Minh', 'Đại Việt', 'Hải Nam', 'Phú Gia', 'Thiên An', 'Trường Sơn'];
  return Array.from({ length: 24 }, (_, i) => ({
    id: i + 1,
    code: 'DH-' + (1001 + i),
    name: names[i % 8],
    region: REGIONS[Math.floor(i / 3) % 3],
    status: (['pending', 'active', 'done'] as const)[i % 3],
    amount: (i + 2) * 1750000,
    owner: ['Lan', 'Minh', 'Hà', 'Nam'][i % 4],
  }));
}

import { ChangeDetectionStrategy, Component, computed, input, signal } from '@angular/core';
import { ScoreCard, ScorecardStripComponent } from '../../components/scorecard-strip.component';
import { seedOrders, STATUS_LABELS } from '../../data/pattern-query';
@Component({
  selector: 'app-pattern-scores',
  imports: [ScorecardStripComponent],
  templateUrl: './scores.component.html',
  styleUrl: '../../styles/patterns.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ScoresComponent {
  readonly variant = input('metric');
  readonly selected = signal('');
  readonly rows = seedOrders();
  readonly labels = STATUS_LABELS;
  readonly interactive = computed(() => ['filter', 'icon-filter'].includes(this.variant()));
  readonly filtered = computed(() => this.rows.filter(r => !this.selected() || r.status === this.selected()));
  readonly iconLayout = computed(() =>
    this.variant() === 'icon-inline' || this.variant() === 'icon-filter'
      ? ('inline' as const)
      : this.variant().startsWith('icon-')
        ? ('tile' as const)
        : ('none' as const)
  );
  readonly cards = computed<ScoreCard[]>(() => {
    const v = this.variant();
    const status = Object.entries(STATUS_LABELS).map(([id, label]) => ({
      id,
      label,
      value: this.rows.filter(r => r.status === id).length,
      hint: 'Toàn bộ dữ liệu mẫu',
      icon: id === 'pending' ? 'schedule' : id === 'active' ? 'sync' : 'check_circle',
      tone: id,
    }));
    if (this.interactive())
      return [{ id: '', label: 'Tất cả đơn hàng', value: this.rows.length, hint: 'Chọn để lọc', icon: 'receipt_long' }, ...status];
    if (v === 'icon-status' || v === 'compact') return status;
    if (v === 'progress')
      return [{ id: 'progress', label: 'Tiến độ hoàn tất', value: '62%', hint: '31 / 50 yêu cầu đã hoàn tất', progress: 62 }];
    if (v === 'comparison')
      return [{ id: 'comparison', label: 'Đơn hàng tháng 9', value: 120, hint: 'Tháng 8: 100 đơn · Chênh lệch +20%' }];
    const total = this.rows.reduce((sum, r) => sum + r.amount, 0);
    const money = {
      id: 'amount',
      label: 'Giá trị đơn hàng',
      value: total / 1000000 + ' triệu ₫',
      hint: '24 đơn hàng · Toàn bộ dữ liệu mẫu',
      icon: 'payments',
    };
    if (v === 'metric') return [money];
    return [
      { id: 'orders', label: 'Tổng đơn hàng', value: 24, hint: 'Toàn bộ dữ liệu mẫu', icon: 'receipt_long' },
      { id: 'customers', label: 'Khách hàng', value: 8, hint: 'Khách hàng có đơn hàng', icon: 'groups' },
      money,
    ];
  });
}

