import { DOCUMENT } from '@angular/common';
import { ChangeDetectionStrategy, Component, inject, signal, viewChild } from '@angular/core';
import { SdButton } from '@sdcorejs/angular/components/button';
import { SdSideDrawer } from '@sdcorejs/angular/components/side-drawer';
import { PatternOrder, STATUS_LABELS } from '../data/pattern-query';
@Component({
  selector: 'app-pattern-order-detail',
  imports: [SdButton, SdSideDrawer],
  templateUrl: './order-detail.component.html',
  styleUrl: '../styles/patterns.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class OrderDetailComponent {
  readonly drawer = viewChild.required(SdSideDrawer);
  readonly record = signal<PatternOrder | null>(null);
  readonly labels = STATUS_LABELS;
  private readonly document = inject(DOCUMENT);
  private opener: HTMLElement | null = null;
  open(row: PatternOrder): void {
    this.opener = this.document.activeElement as HTMLElement;
    this.record.set(row);
    this.drawer().open();
  }
  restore(): void {
    const opener = this.opener;
    requestAnimationFrame(() => {
      if (opener?.isConnected) opener.focus();
    });
  }
}

import { ChangeDetectionStrategy, Component, input, output } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { SdButton } from '@sdcorejs/angular/components/button';
import { PatternQuery, REGIONS } from '../data/pattern-query';
@Component({
  selector: 'app-pattern-query',
  imports: [FormsModule, SdButton],
  templateUrl: './query-bar.component.html',
  styleUrl: '../styles/patterns.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class QueryBarComponent {
  readonly query = input.required<PatternQuery>();
  readonly changed = output<PatternQuery>();
  readonly regions = REGIONS;
  change(patch: Partial<PatternQuery>): void {
    this.changed.emit({ ...this.query(), ...patch });
  }
  clear(): void {
    this.changed.emit({ search: '', status: '', region: '', sort: 'code' });
  }
}

import { ChangeDetectionStrategy, Component, computed, effect, input, output, viewChild } from '@angular/core';
import { SdTable, SdTableCellDefDirective, SdTableOption } from '@sdcorejs/angular/components/table';
import { PatternOrder, STATUS_LABELS } from '../data/pattern-query';
@Component({
  selector: 'app-pattern-results',
  imports: [SdTable, SdTableCellDefDirective],
  templateUrl: './results-table.component.html',
  styleUrl: '../styles/patterns.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class ResultsTableComponent {
  readonly table = viewChild(SdTable);
  constructor() {
    effect(onCleanup => {
      const table = this.table();
      const paginator = table?.paginator();
      if (!table || !paginator) return;
      // The view query resolves before Core applies its configured initial size.
      let pageSize = this.option().paginate?.pageSize ?? 6;
      const subscription = paginator.page.subscribe(event => {
        // Flush Core's pending initial filter notification without resetting this page.
        table.onFilterCommit();
        if (pageSize === event.pageSize) return;
        pageSize = event.pageSize;
        table.onClearSelection();
        paginator.firstPage();
      });
      onCleanup(() => subscription.unsubscribe());
    });
    effect(onCleanup => {
      const table = this.table();
      const sort = table?.sort();
      const paginator = table?.paginator();
      if (!table || !sort || !paginator) return;
      const subscription = sort.sortChange.subscribe(() => {
        table.onClearSelection();
        table.onFilterCommit();
        paginator.firstPage();
      });
      onCleanup(() => subscription.unsubscribe());
    });
  }
  readonly rows = input.required<PatternOrder[]>();
  readonly selectable = input(false);
  readonly quickSearch = input(false);
  readonly openRecord = output<PatternOrder>();
  readonly approve = output<number[]>();
  readonly option = computed<SdTableOption<PatternOrder>>(() => {
    const rows = this.rows();
    return {
      type: 'local',
      rowKey: 'id',
      sort: { enable: true },
      items: () => rows,
      columns: [
        { field: 'code', title: 'Mã đơn', type: 'string', width: '120px', sortable: true },
        { field: 'name', title: 'Khách hàng', type: 'string', width: '180px', sortable: true },
        { field: 'region', title: 'Khu vực', type: 'string', width: '120px' },
        {
          field: 'status',
          title: 'Trạng thái',
          type: 'values',
          width: '150px',
          option: { items: Object.entries(STATUS_LABELS).map(([id, name]) => ({ id, name })), valueField: 'id', displayField: 'name' },
          useBadge: (_value, row) => ({
            title: STATUS_LABELS[row.status],
            color: row.status === 'pending' ? 'warning' : row.status === 'done' ? 'success' : 'info',
          }),
        },
        { field: 'amount', title: 'Giá trị (VND)', type: 'number', align: 'right', width: '150px', sortable: true },
      ],
      paginate: { pageSize: 6, pages: [6, 12, 24] },
      config: { visible: true },
      filter: {
        cacheable: false,
        hideInlineFilter: true,
        hideExternalFilterToolbar: true,
        ...(this.quickSearch() ? { quickSearch: { containFields: ['code', 'name'], placeholder: 'Tìm mã hoặc tên' } } : {}),
      },
      ...(this.selectable()
        ? {
            selector: {
              visible: true,
              actions: [
                {
                  title: 'Duyệt đơn hàng',
                  icon: 'check_circle',
                  click: (selected: PatternOrder[]) => this.approve.emit(selected.map(r => r.id)),
                },
              ],
            },
          }
        : {}),
    };
  });
}

export type OrderStatus = 'pending' | 'active' | 'done';
export interface PatternOrder {
  id: number;
  code: string;
  name: string;
  region: string;
  status: OrderStatus;
  amount: number;
  owner: string;
}
export interface PatternQuery {
  search: string;
  status: string;
  region: string;
  sort: string;
}
export const EMPTY_QUERY: PatternQuery = { search: '', status: '', region: '', sort: 'code' };
export const STATUS_LABELS: Record<OrderStatus, string> = { pending: 'Chờ xử lý', active: 'Đang xử lý', done: 'Hoàn tất' };
export const REGIONS = ['Miền Bắc', 'Miền Trung', 'Miền Nam'];
export const normalizeSearch = (value: string) =>
  value
    .normalize('NFD')
    .replace(/[\u0300-\u036f]/g, '')
    .replace(/[đĐ]/g, 'd')
    .toLowerCase()
    .trim();
export function queryOrders(records: readonly PatternOrder[], query: PatternQuery): PatternOrder[] {
  return records
    .filter(
      row =>
        (!query.status || row.status === query.status) &&
        (!query.region || row.region === query.region) &&
        normalizeSearch(row.code + ' ' + row.name).includes(normalizeSearch(query.search))
    )
    .sort(
      (a, b) => (query.sort === 'amount-desc' ? b.amount - a.amount : query.sort === 'amount-asc' ? a.amount - b.amount : 0) || a.id - b.id
    );
}
export function seedOrders(): PatternOrder[] {
  const names = ['An Phát', 'Minh Long', 'Bình Minh', 'Đại Việt', 'Hải Nam', 'Phú Gia', 'Thiên An', 'Trường Sơn'];
  return Array.from({ length: 24 }, (_, i) => ({
    id: i + 1,
    code: 'DH-' + (1001 + i),
    name: names[i % 8],
    region: REGIONS[Math.floor(i / 3) % 3],
    status: (['pending', 'active', 'done'] as const)[i % 3],
    amount: (i + 2) * 1750000,
    owner: ['Lan', 'Minh', 'Hà', 'Nam'][i % 4],
  }));
}

import { Injectable, signal } from '@angular/core';
import { OrderStatus, seedOrders } from './pattern-query';
@Injectable()
export class PatternStore {
  readonly records = signal(seedOrders());
  readonly pending = signal<number[]>([]);
  readonly message = signal('');
  readonly simulateError = signal(false);
  async transition(ids: number[], status: OrderStatus): Promise<boolean> {
    if (!ids.length || this.pending().length) return false;
    this.pending.set(ids);
    this.message.set('');
    const fail = this.simulateError();
    try {
      await new Promise(resolve => setTimeout(resolve, 350));
      if (fail) throw new Error('Không thể cập nhật. Dữ liệu được giữ nguyên; hãy thử lại.');
      this.records.update(rows => rows.map(row => (ids.includes(row.id) ? { ...row, status } : row)));
      this.message.set('Đã cập nhật ' + ids.length + ' đơn hàng.');
      return true;
    } catch (error) {
      this.message.set((error as Error).message);
      return false;
    } finally {
      this.pending.set([]);
    }
  }
  reset(): void {
    if (!this.pending().length) {
      this.records.set(seedOrders());
      this.message.set('Đã khôi phục dữ liệu mẫu.');
    }
  }
}

import { ChangeDetectionStrategy, Component, computed, inject, input, signal } from '@angular/core';
import { FormsModule } from '@angular/forms';
import { SdButton } from '@sdcorejs/angular/components/button';
import { SdDataState } from '@sdcorejs/angular/components/data-state';
import { ResultsTableComponent } from '../../components/results-table.component';
import { QueryBarComponent } from '../../components/query-bar.component';
import { OrderDetailComponent } from '../../components/order-detail.component';
import { PatternStore } from '../../data/pattern-store';
import { EMPTY_QUERY, PatternQuery, queryOrders } from '../../data/pattern-query';
@Component({
  selector: 'app-pattern-tables',
  imports: [FormsModule, SdButton, SdDataState, ResultsTableComponent, QueryBarComponent, OrderDetailComponent],
  providers: [PatternStore],
  templateUrl: './tables.component.html',
  styleUrl: '../../styles/patterns.scss',
  changeDetection: ChangeDetectionStrategy.OnPush,
})
export class TablesComponent {
  readonly variant = input('standard');
  readonly store = inject(PatternStore);
  readonly query = signal<PatternQuery>({ ...EMPTY_QUERY });
  readonly rows = computed(() => queryOrders(this.store.records(), this.query()));
  readonly expanded = signal(true);
  readonly state = signal<'loading' | 'empty' | 'error' | 'no-results'>('loading');
  readonly coreState = computed(() => {
    const state = this.state();
    return state === 'no-results' ? 'empty' : state;
  });
}

